function node(v,level){ var f=new Array(level+1).fill(null); return {v:v, forward:f}; }
function SkipList(maxLevel,p){ this.maxLevel=maxLevel; this.p=p; this.head=node(-Infinity,maxLevel); this.level=0; }
SkipList.prototype.randomLevel=function(){ var l=0; while(Math.random()<this.p && l<this.maxLevel) l++; return l; };
SkipList.prototype.insert=function(v){ var update=new Array(this.maxLevel+1).fill(null); var x=this.head;
  for(var i=this.level;i>=0;i--){ while(x.forward[i] && x.forward[i].v<v) x=x.forward[i]; update[i]=x; }
  x=x.forward[0];
  if(x && x.v===v) return false;
  var lvl=this.randomLevel();
  if(lvl>this.level){ for(var i=this.level+1;i<=lvl;i++) update[i]=this.head; this.level=lvl; }
  var nn=node(v,lvl);
  for(var i=0;i<=lvl;i++){ nn.forward[i]=update[i].forward[i]; update[i].forward[i]=nn; }
  return true; };
SkipList.prototype.search=function(v){ var x=this.head; for(var i=this.level;i>=0;i--){ while(x.forward[i] && x.forward[i].v<v) x=x.forward[i]; } x=x.forward[0]; return (x && x.v===v); };
SkipList.prototype.toSorted=function(){ var out=[]; var x=this.head.forward[0]; while(x){ out.push(x.v); x=x.forward[0]; } return out; };
function makeSkipList(){ return new SkipList(4,0.5); }
var EXPORTS={makeSkipList:makeSkipList};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SkipListForgePure = EXPORTS; }
